#### Step 2: Implement Error Factory/Builder

Create shared library for generating standard error responses:

**.NET Core Implementation**:

```csharp
// Gainwell.Api.ErrorHandling/ProblemDetailsFactory.cs
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using System.Diagnostics;

namespace Gainwell.Api.ErrorHandling
{
    public interface IProblemDetailsFactory
    {
        ProblemDetails CreateValidationError(string detail,
            IEnumerable<ValidationError> errors);
        ProblemDetails CreateBusinessRuleError(string errorType,
            string title, string detail, string suggestedAction = null);
        ProblemDetails CreateNotFoundError(string resourceType,
            string resourceId);
        ProblemDetails CreateServerError(string message = null);
    }

    public class ProblemDetailsFactory : IProblemDetailsFactory
    {
        private readonly IHttpContextAccessor _contextAccessor;
        private readonly IConfiguration _config;
        private readonly ILogger<ProblemDetailsFactory> _logger;

        private const string ErrorBaseUrl = "https://api.gainwell.com/errors";
        private const string DocsBaseUrl = "https://api.gainwell.com/docs/errors";

        public ProblemDetailsFactory(
            IHttpContextAccessor contextAccessor,
            IConfiguration config,
            ILogger<ProblemDetailsFactory> logger)
        {
            _contextAccessor = contextAccessor;
            _config = config;
            _logger = logger;
        }

        public ProblemDetails CreateValidationError(
            string detail,
            IEnumerable<ValidationError> errors)
        {
            var problemDetails = CreateBaseProblemDetails(
                type: $"{ErrorBaseUrl}/validation/invalid-input",
                title: "Validation Failed",
                status: StatusCodes.Status400BadRequest,
                detail: detail
            );

            problemDetails.Extensions["errors"] = errors.Select(e => new
            {
                field = e.Field,
                code = e.Code,
                message = e.Message,
                rejectedValue = e.RejectedValue
            });

            problemDetails.Extensions["suggestedAction"] =
                "Review the validation errors and correct the indicated fields";

            return problemDetails;
        }

        public ProblemDetails CreateBusinessRuleError(
            string errorType,
            string title,
            string detail,
            string suggestedAction = null)
        {
            var problemDetails = CreateBaseProblemDetails(
                type: $"{ErrorBaseUrl}/business-rule/{errorType}",
                title: title,
                status: StatusCodes.Status422UnprocessableEntity,
                detail: detail
            );

            if (!string.IsNullOrEmpty(suggestedAction))
            {
                problemDetails.Extensions["suggestedAction"] = suggestedAction;
            }

            return problemDetails;
        }

        public ProblemDetails CreateNotFoundError(
            string resourceType,
            string resourceId)
        {
            var problemDetails = CreateBaseProblemDetails(
                type: $"{ErrorBaseUrl}/resource/not-found",
                title: "Resource Not Found",
                status: StatusCodes.Status404NotFound,
                detail: $"{resourceType} with ID '{resourceId}' was not found"
            );

            problemDetails.Extensions["suggestedAction"] =
                $"Verify the {resourceType} ID is correct and the resource exists";

            return problemDetails;
        }

        public ProblemDetails CreateServerError(string message = null)
        {
            var sanitizedMessage = message != null
                ? SanitizeErrorMessage(message)
                : "An unexpected error occurred while processing your request";

            var problemDetails = CreateBaseProblemDetails(
                type: $"{ErrorBaseUrl}/server/internal-error",
                title: "Internal Server Error",
                status: StatusCodes.Status500InternalServerError,
                detail: sanitizedMessage
            );

            problemDetails.Extensions["suggestedAction"] =
                "This error has been logged. Please retry your request. " +
                "If the issue persists, contact support with the correlation ID.";

            problemDetails.Extensions["supportContact"] =
                _config["Support:Email"] ?? "api-support@gainwell.com";

            return problemDetails;
        }

        private ProblemDetails CreateBaseProblemDetails(
            string type,
            string title,
            int status,
            string detail)
        {
            var context = _contextAccessor.HttpContext;
            var correlationId = Activity.Current?.Id ??
                context?.TraceIdentifier ??
                Guid.NewGuid().ToString();

            var problemDetails = new ProblemDetails
            {
                Type = type,
                Title = title,
                Status = status,
                Detail = detail,
                Instance = $"{context?.Request.Path}/{context?.TraceIdentifier}"
            };

            problemDetails.Extensions["timestamp"] = DateTime.UtcNow;
            problemDetails.Extensions["correlationId"] = correlationId;
            problemDetails.Extensions["documentationUrl"] =
                $"{DocsBaseUrl}/{type.Replace(ErrorBaseUrl + "/", "")}";

            // Set correlation ID header
            if (context != null)
            {
                context.Response.Headers["X-Correlation-Id"] = correlationId;
            }

            return problemDetails;
        }

        private string SanitizeErrorMessage(string message)
        {
            // Remove potential PHI, stack traces, file paths
            if (string.IsNullOrWhiteSpace(message))
            {
                return "An unexpected error occurred";
            }

            // Check for patterns indicating sensitive data
            if (message.Contains("Exception") ||
                message.Contains("\\") ||
                message.Contains("password", StringComparison.OrdinalIgnoreCase) ||
                message.Contains("connection", StringComparison.OrdinalIgnoreCase))
            {
                _logger.LogWarning("Sanitizing potentially sensitive error message");
                return "An unexpected error occurred while processing your request";
            }

            return message;
        }
    }

    public record ValidationError(
        string Field,
        string Code,
        string Message,
        object RejectedValue = null);
}
```

