#### Step 3: Configure Global Exception Handler

Register middleware to catch unhandled exceptions and convert to RFC 7807 format:

```csharp
// Program.cs or Startup.cs
public class Program
{
    public static void Main(string[] args)
    {
        var builder = WebApplication.CreateBuilder(args);

        // Register services
        builder.Services.AddHttpContextAccessor();
        builder.Services.AddScoped<IProblemDetailsFactory, ProblemDetailsFactory>();

        // Configure ProblemDetails
        builder.Services.AddProblemDetails(options =>
        {
            options.CustomizeProblemDetails = context =>
            {
                // Ensure all responses have correlation ID
                var correlationId = context.HttpContext.TraceIdentifier;
                context.ProblemDetails.Extensions["correlationId"] = correlationId;
                context.ProblemDetails.Extensions["timestamp"] = DateTime.UtcNow;
                context.HttpContext.Response.Headers["X-Correlation-Id"] = correlationId;
            };
        });

        builder.Services.AddControllers();

        var app = builder.Build();

        // Use exception handler middleware
        app.UseExceptionHandler(errorApp =>
        {
            errorApp.Run(async context =>
            {
                var problemDetailsFactory = context.RequestServices
                    .GetRequiredService<IProblemDetailsFactory>();
                var logger = context.RequestServices
                    .GetRequiredService<ILogger<Program>>();

                var exceptionFeature = context.Features
                    .Get<IExceptionHandlerFeature>();

                if (exceptionFeature != null)
                {
                    var exception = exceptionFeature.Error;

                    // Log full exception details
                    logger.LogError(exception,
                        "Unhandled exception occurred: {Message}",
                        exception.Message);

                    // Create sanitized error response
                    var problemDetails = problemDetailsFactory.CreateServerError();

                    context.Response.StatusCode =
                        problemDetails.Status ?? StatusCodes.Status500InternalServerError;
                    context.Response.ContentType = "application/problem+json";

                    await context.Response.WriteAsJsonAsync(problemDetails);
                }
            });
        });

        app.UseRouting();
        app.UseAuthentication();
        app.UseAuthorization();
        app.MapControllers();

        app.Run();
    }
}
```

