[patterns/application/api-microservices/PTN-APP-API-011-error-response-pattern.md#step-4-implement-in-api-controllers]

#### Step 4: Implement in API Controllers

Use error factory in controllers to return standard responses:

```csharp
[ApiController]
[Route("api/v1/[controller]")]
public class ClaimsController : ControllerBase
{
    private readonly IClaimService _claimService;
    private readonly IProblemDetailsFactory _problemDetailsFactory;
    private readonly ILogger<ClaimsController> _logger;

    public ClaimsController(
        IClaimService claimService,
        IProblemDetailsFactory problemDetailsFactory,
        ILogger<ClaimsController> logger)
    {
        _claimService = claimService;
        _problemDetailsFactory = problemDetailsFactory;
        _logger = logger;
    }

    [HttpPost]
    [ProducesResponseType(typeof(ClaimResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status422UnprocessableEntity)]
    public async Task<IActionResult> SubmitClaim([FromBody] ClaimSubmission request)
    {
        // Validate request
        var validationErrors = ValidateClaimSubmission(request);
        if (validationErrors.Any())
        {
            var problemDetails = _problemDetailsFactory.CreateValidationError(
                $"Request validation failed on {validationErrors.Count} field(s)",
                validationErrors
            );
            return BadRequest(problemDetails);
        }

        // Check business rules
        var eligibility = await _claimService.CheckEligibility(
            request.MemberId,
            request.ServiceDate
        );

        if (!eligibility.IsEligible)
        {
            var problemDetails = _problemDetailsFactory.CreateBusinessRuleError(
                errorType: "eligibility-not-met",
                title: "Member Not Eligible",
                detail: $"Member {request.MemberId} was not eligible for " +
                       $"services on {request.ServiceDate:yyyy-MM-dd}",
                suggestedAction: "Verify the member ID and service date. " +
                               "Check eligibility before submitting claims."
            );
            return UnprocessableEntity(problemDetails);
        }

        // Process claim
        var result = await _claimService.SubmitClaimAsync(request);

        return CreatedAtAction(
            nameof(GetClaim),
            new { id = result.ClaimId },
            result
        );
    }

    [HttpGet("{id}")]
    [ProducesResponseType(typeof(ClaimResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound)]
    public async Task<IActionResult> GetClaim(string id)
    {
        var claim = await _claimService.GetClaimAsync(id);

        if (claim == null)
        {
            var problemDetails = _problemDetailsFactory.CreateNotFoundError(
                resourceType: "Claim",
                resourceId: id
            );
            return NotFound(problemDetails);
        }

        return Ok(claim);
    }

    private List<ValidationError> ValidateClaimSubmission(ClaimSubmission request)
    {
        var errors = new List<ValidationError>();

        if (string.IsNullOrWhiteSpace(request.MemberId))
        {
            errors.Add(new ValidationError(
                Field: "memberId",
                Code: "REQUIRED_FIELD",
                Message: "Member ID is required"
            ));
        }

        if (request.ServiceDate > DateTime.Today)
        {
            errors.Add(new ValidationError(
                Field: "serviceDate",
                Code: "INVALID_DATE",
                Message: "Service date cannot be in the future",
                RejectedValue: request.ServiceDate
            ));
        }

        if (request.BilledAmount <= 0)
        {
            errors.Add(new ValidationError(
                Field: "billedAmount",
                Code: "INVALID_VALUE",
                Message: "Billed amount must be greater than zero",
                RejectedValue: request.BilledAmount
            ));
        }

        return errors;
    }
}
```

