#### Step 5: Configure API Gateway Error Transformation

Set up Azure API Management policy to transform gateway errors:

```xml
<!-- Azure APIM Policy -->
<policies>
    <inbound>
        <!-- Generate correlation ID if not present -->
        <set-variable name="correlationId"
            value="@(context.RequestId)" />
        <set-header name="X-Correlation-Id"
            exists-action="skip">
            <value>@((string)context.Variables["correlationId"])</value>
        </set-header>
    </inbound>
    <backend>
        <forward-request />
    </backend>
    <outbound>
        <!-- Add correlation ID to all responses -->
        <set-header name="X-Correlation-Id"
            exists-action="override">
            <value>@((string)context.Variables["correlationId"])</value>
        </set-header>
    </outbound>
    <on-error>
        <!-- Transform errors to RFC 7807 format -->
        <set-status code="@(context.LastError.StatusCode)"
            reason="@(context.LastError.Reason)" />
        <set-header name="Content-Type"
            exists-action="override">
            <value>application/problem+json</value>
        </set-header>
        <set-header name="X-Correlation-Id"
            exists-action="override">
            <value>@((string)context.Variables["correlationId"])</value>
        </set-header>
        <set-body>@{
            var errorType = "";
            var title = "";
            var suggestedAction = "";

            switch (context.LastError.StatusCode)
            {
                case 401:
                    errorType = "authentication/invalid-credentials";
                    title = "Authentication Required";
                    suggestedAction = "Provide valid credentials in the Authorization header";
                    break;
                case 403:
                    errorType = "authorization/insufficient-permissions";
                    title = "Access Forbidden";
                    suggestedAction = "Verify you have permission to access this resource";
                    break;
                case 429:
                    errorType = "rate-limit/quota-exceeded";
                    title = "Rate Limit Exceeded";
                    suggestedAction = "Reduce request rate or contact support to increase quota";
                    break;
                case 503:
                    errorType = "service-unavailable/maintenance";
                    title = "Service Unavailable";
                    suggestedAction = "The service is temporarily unavailable. Please retry after some time";
                    break;
                default:
                    errorType = "server/gateway-error";
                    title = "Gateway Error";
                    suggestedAction = "An error occurred at the API gateway. Please retry your request";
                    break;
            }

            var problemDetails = new JObject(
                new JProperty("type", $"https://api.gainwell.com/errors/{errorType}"),
                new JProperty("title", title),
                new JProperty("status", context.LastError.StatusCode),
                new JProperty("detail", context.LastError.Message),
                new JProperty("instance", context.Request.Url.Path),
                new JProperty("timestamp", DateTime.UtcNow.ToString("o")),
                new JProperty("correlationId", context.Variables["correlationId"]),
                new JProperty("suggestedAction", suggestedAction),
                new JProperty("documentationUrl",
                    $"https://api.gainwell.com/docs/errors/{errorType}")
            );

            return problemDetails.ToString();
        }</set-body>
    </on-error>
</policies>
```

