**JavaScript/Node.js Error Middleware**:

```javascript
// error-handler.js
const { v4: uuidv4 } = require('uuid');

function createProblemDetails(type, title, status, detail, req, extensions = {}) {
  const correlationId = req.id || req.headers['x-correlation-id'] || uuidv4();

  return {
    type: `https://api.gainwell.com/errors/${type}`,
    title,
    status,
    detail,
    instance: `${req.path}/${req.id}`,
    timestamp: new Date().toISOString(),
    correlationId,
    documentationUrl: `https://api.gainwell.com/docs/errors/${type}`,
    ...extensions
  };
}

function errorHandler(err, req, res, next) {
  const logger = req.app.get('logger');

  // Log full error details
  logger.error({
    error: err.message,
    stack: err.stack,
    correlationId: req.id,
    path: req.path,
    method: req.method
  });

  let problemDetails;

  if (err.name === 'ValidationError') {
    problemDetails = createProblemDetails(
      'validation/invalid-input',
      'Validation Failed',
      400,
      'Request validation failed',
      req,
      {
        errors: err.errors.map(e => ({
          field: e.field,
          code: e.code,
          message: e.message
        })),
        suggestedAction: 'Review validation errors and correct the indicated fields'
      }
    );
  } else if (err.name === 'UnauthorizedError') {
    problemDetails = createProblemDetails(
      'authentication/invalid-credentials',
      'Authentication Required',
      401,
      'Invalid or missing authentication credentials',
      req,
      {
        suggestedAction: 'Provide valid credentials in the Authorization header'
      }
    );
  } else if (err.name === 'ForbiddenError') {
    problemDetails = createProblemDetails(
      'authorization/insufficient-permissions',
      'Access Forbidden',
      403,
      'You do not have permission to access this resource',
      req,
      {
        suggestedAction: 'Verify you have the required permissions'
      }
    );
  } else if (err.name === 'NotFoundError') {
    problemDetails = createProblemDetails(
      'resource/not-found',
      'Resource Not Found',
      404,
      err.message || 'The requested resource was not found',
      req,
      {
        suggestedAction: 'Verify the resource ID and try again'
      }
    );
  } else {
    // Generic server error
    problemDetails = createProblemDetails(
      'server/internal-error',
      'Internal Server Error',
      500,
      'An unexpected error occurred',
      req,
      {
        suggestedAction: 'This error has been logged. Please retry your request. ' +
          'If the issue persists, contact support with the correlation ID.',
        supportContact: 'api-support@gainwell.com'
      }
    );
  }

  res.setHeader('Content-Type', 'application/problem+json');
  res.setHeader('X-Correlation-Id', problemDetails.correlationId);
  res.status(problemDetails.status).json(problemDetails);
}

module.exports = { errorHandler, createProblemDetails };
```

